ALTER TYPE agg.metric_category ADD VALUE IF NOT EXISTS 'results';
ALTER TYPE agg.metric_category ADD VALUE IF NOT EXISTS 'attack';
ALTER TYPE agg.metric_category ADD VALUE IF NOT EXISTS 'defence';
ALTER TYPE agg.metric_category ADD VALUE IF NOT EXISTS 'control';
ALTER TYPE agg.metric_category ADD VALUE IF NOT EXISTS 'pressing';
