CREATE TYPE agg.run_kind AS ENUM ('percentiles', 'index', 'roles', 'similarity', 'levels', 'projection', 'award', 'strength');
CREATE TYPE agg.run_status AS ENUM ('running', 'published', 'superseded', 'failed');
CREATE TYPE agg.agg_rule AS ENUM ('sum', 'ratio', 'weighted_mean', 'match_mean', 'max', 'rating', 'recompute');
CREATE TYPE agg.universe_kind AS ENUM ('league', 'competition', 'europe');
CREATE TYPE agg.stat_scope AS ENUM ('league', 'league_and_uefa');
CREATE TYPE agg.award_kind AS ENUM ('ballon_dor');

-- Which model, formulas and data produced a published result.
CREATE TABLE agg.calc_runs(
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind agg.run_kind NOT NULL,
  model_version text NOT NULL,
  formula_version text,
  data_revision bigint,
  cohort_definition text,
  cutoff_at timestamptz,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  status agg.run_status NOT NULL DEFAULT 'running',
  CHECK (finished_at IS NULL OR finished_at >= started_at)
);

CREATE TABLE agg.metric_definitions(
  entity_type core.entity_type NOT NULL CHECK (entity_type IN ('player', 'team')),
  key text NOT NULL,
  label_fr text,
  category agg.metric_category,
  source_family text NOT NULL CHECK (source_family IN ('base', 'advanced', 'derived')),
  aggregation agg.agg_rule NOT NULL,
  numerator_key text,
  denominator_key text,
  weight_key text,
  coverage_group text,
  min_minutes integer CHECK (min_minutes >= 0),
  unit text,
  per90 boolean NOT NULL DEFAULT false,
  direction smallint NOT NULL DEFAULT 1 CHECK (direction IN (-1, 0, 1)),
  decimals smallint CHECK (decimals BETWEEN 0 AND 4),
  formula text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (entity_type, key),
  CHECK ((aggregation = 'ratio') = (numerator_key IS NOT NULL AND denominator_key IS NOT NULL)),
  CHECK ((aggregation = 'weighted_mean') <= (weight_key IS NOT NULL))
);

