  CHECK (won + drawn + lost = matches)
);
CREATE INDEX team_season_stats_edition ON agg.team_season_stats(competition_season_id);

CREATE TABLE agg.team_game_states(
  team_id integer NOT NULL REFERENCES core.teams,
  competition_season_id integer NOT NULL REFERENCES core.competition_seasons,
  season_id smallint NOT NULL REFERENCES core.seasons,
  matches integer NOT NULL CHECK (matches >= 0),
  scored_first integer NOT NULL DEFAULT 0,
  scored_first_won integer NOT NULL DEFAULT 0,
  scored_first_drawn integer NOT NULL DEFAULT 0,
  scored_first_lost integer NOT NULL DEFAULT 0,
  scored_first_points integer NOT NULL DEFAULT 0,
  conceded_first integer NOT NULL DEFAULT 0,
  conceded_first_won integer NOT NULL DEFAULT 0,
  conceded_first_drawn integer NOT NULL DEFAULT 0,
  conceded_first_lost integer NOT NULL DEFAULT 0,
  conceded_first_points integer NOT NULL DEFAULT 0,
  goalless integer NOT NULL DEFAULT 0,
  points_from_behind integer NOT NULL DEFAULT 0,
  points_dropped_from_lead integer NOT NULL DEFAULT 0,
  minutes_leading integer NOT NULL DEFAULT 0,
  minutes_level integer NOT NULL DEFAULT 0,
  minutes_trailing integer NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, competition_season_id)
);

CREATE TABLE agg.team_squad_profile(
  team_id integer NOT NULL REFERENCES core.teams,
  season_id smallint NOT NULL REFERENCES core.seasons,
  squad_value_eur bigint CHECK (squad_value_eur >= 0),
  value_rank smallint CHECK (value_rank >= 1),
  age_weighted real,
  minutes_u21 integer,
  minutes_21_23 integer,
  minutes_24_26 integer,
  minutes_27_29 integer,
  minutes_30_32 integer,
  minutes_33_plus integer,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, season_id)
);

CREATE TABLE agg.team_levels(
  team_id integer NOT NULL REFERENCES core.teams,
  season_id smallint NOT NULL REFERENCES core.seasons,
  level real NOT NULL,
  season_part real,
  long_run_part real,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, season_id)
);

CREATE TABLE agg.cohorts(
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entity_type core.entity_type NOT NULL CHECK (entity_type IN ('player', 'team')),
  label text NOT NULL,
  season_id smallint NOT NULL REFERENCES core.seasons,
  universe agg.universe_kind NOT NULL,
  stat_scope agg.stat_scope NOT NULL DEFAULT 'league',
  position_group text,
  min_minutes integer CHECK (min_minutes >= 0),
  per_match boolean NOT NULL DEFAULT false,
  size integer CHECK (size >= 0),
  calc_run_id integer REFERENCES agg.calc_runs,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((entity_type = 'team') <= (position_group IS NULL))
);
ALTER TABLE ops.dirty_scopes ADD CONSTRAINT dirty_scopes_cohort_id_fkey
  FOREIGN KEY (cohort_id) REFERENCES agg.cohorts;

CREATE TABLE agg.cohort_competitions(
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  competition_id integer NOT NULL REFERENCES core.competitions,
  PRIMARY KEY (cohort_id, competition_id)
);

CREATE TABLE agg.cohort_distributions(
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  metric_key text NOT NULL,
  p10 real, p25 real, p50 real, p75 real, p90 real,
  min real, max real,
  n integer NOT NULL CHECK (n >= 0),
  PRIMARY KEY (cohort_id, metric_key)
);

CREATE TABLE agg.player_percentiles(
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  player_id integer NOT NULL REFERENCES core.players,
  metric_key text NOT NULL,
  value_p90 real,
  covered_minutes integer CHECK (covered_minutes >= 0),
  percentile smallint CHECK (percentile BETWEEN 0 AND 100),
  rank integer CHECK (rank >= 1),
  PRIMARY KEY (cohort_id, player_id, metric_key)
);
CREATE INDEX player_percentiles_player ON agg.player_percentiles(player_id);

CREATE TABLE agg.team_percentiles(
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  team_id integer NOT NULL REFERENCES core.teams,
  metric_key text NOT NULL,
  value real,
  covered_matches integer CHECK (covered_matches >= 0),
  percentile smallint CHECK (percentile BETWEEN 0 AND 100),
  rank integer CHECK (rank >= 1),
  PRIMARY KEY (cohort_id, team_id, metric_key)
);
CREATE INDEX team_percentiles_team ON agg.team_percentiles(team_id);

CREATE TABLE agg.role_definitions(
  code text PRIMARY KEY,
  label_fr text NOT NULL,
  position_group text NOT NULL
);

CREATE TABLE agg.role_weights(
  role_code text NOT NULL REFERENCES agg.role_definitions,
  metric_key text NOT NULL,
  weight real NOT NULL,
  PRIMARY KEY (role_code, metric_key)
);

CREATE TABLE agg.player_role_scores(
  player_id integer NOT NULL REFERENCES core.players,
  season_id smallint NOT NULL REFERENCES core.seasons,
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  role_code text NOT NULL REFERENCES agg.role_definitions,
  score smallint CHECK (score BETWEEN 0 AND 100),
  rank integer CHECK (rank >= 1),
  cohort_size integer,
  is_primary boolean NOT NULL DEFAULT false,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (player_id, season_id, cohort_id, role_code)
);

CREATE TABLE agg.player_similar(
  player_id integer NOT NULL REFERENCES core.players,
  season_id smallint NOT NULL REFERENCES core.seasons,
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  rank smallint NOT NULL CHECK (rank >= 1),
  similar_player_id integer NOT NULL REFERENCES core.players,
  similarity real,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (player_id, season_id, cohort_id, rank),
  CHECK (similar_player_id <> player_id)
);

CREATE TABLE agg.team_similar(
  team_id integer NOT NULL REFERENCES core.teams,
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  rank smallint NOT NULL CHECK (rank >= 1),
  similar_team_id integer NOT NULL REFERENCES core.teams,
  similarity smallint CHECK (similarity BETWEEN 0 AND 100),
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (team_id, cohort_id, rank),
  CHECK (similar_team_id <> team_id)
);

CREATE TABLE agg.player_index(
  player_id integer NOT NULL REFERENCES core.players,
  season_id smallint NOT NULL REFERENCES core.seasons,
  vega_index smallint CHECK (vega_index BETWEEN 0 AND 100),
  potential smallint CHECK (potential BETWEEN 0 AND 100),
  career_stage text,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (player_id, season_id)
);

CREATE TABLE agg.team_index(
  team_id integer NOT NULL REFERENCES core.teams,
  cohort_id integer NOT NULL REFERENCES agg.cohorts ON DELETE CASCADE,
  vega_index smallint CHECK (vega_index BETWEEN 0 AND 100),
  vega_rank integer CHECK (vega_rank >= 1),
  position integer CHECK (position >= 1),
  xpts_position integer CHECK (xpts_position >= 1),
  attack smallint CHECK (attack BETWEEN 0 AND 100),
  defence smallint CHECK (defence BETWEEN 0 AND 100),
  control smallint CHECK (control BETWEEN 0 AND 100),
  pressing smallint CHECK (pressing BETWEEN 0 AND 100),
  set_pieces smallint CHECK (set_pieces BETWEEN 0 AND 100),
  finishing smallint CHECK (finishing BETWEEN 0 AND 100),
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (team_id, cohort_id)
);

CREATE TABLE agg.player_award_ranking(
  season_id smallint NOT NULL REFERENCES core.seasons,
  award agg.award_kind NOT NULL,
  rank smallint NOT NULL CHECK (rank >= 1),
  player_id integer NOT NULL REFERENCES core.players,
  team_id integer REFERENCES core.teams,
  score real,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (season_id, award, rank),
  UNIQUE (season_id, award, player_id)
);

CREATE TABLE agg.competition_strength(
  competition_season_id integer PRIMARY KEY REFERENCES core.competition_seasons,
  strength smallint CHECK (strength BETWEEN 0 AND 100),
  goals_per90 real,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs
);

CREATE TABLE agg.player_projections(
  player_id integer NOT NULL REFERENCES core.players,
  season_id smallint NOT NULL REFERENCES core.seasons,
  horizon_season_id smallint NOT NULL REFERENCES core.seasons,
  metric_key text NOT NULL,
  low real,
  mid real,
  high real,
  calc_run_id integer NOT NULL REFERENCES agg.calc_runs,
  PRIMARY KEY (player_id, season_id, horizon_season_id, metric_key),
  CHECK (horizon_season_id > season_id),
  CHECK (low <= mid AND mid <= high)
);
